	<?php if ($room['status'] === 'published' && ! $ended && $current_user['account_kind'] !== 'child'): ?><details><summary>Ajukan / perbarui pengajuan katalog</summary><?php echo form_open('belajar/battle/ruang/'.$room['id']); ?><input type="hidden" name="revision" value="<?php echo (int) $room['revision']; ?>"><input type="hidden" name="action" value="list_request"><label class="form-label mt-3" for="public-summary">Ringkasan kegiatan untuk semua member</label><textarea class="form-control mb-3" id="public-summary" name="public_summary" minlength="20" maxlength="500" rows="3" required><?php echo html_escape($room['public_summary']); ?></textarea><label class="form-label" for="public-age">Sasaran kegiatan</label><select class="form-select mb-3" id="public-age" name="public_age"><?php foreach (array('primary' => 'SD', 'secondary' => 'SMP', 'all_ages' => 'Lintas jenjang / keluarga') as $key => $label): ?><option value="<?php echo $key; ?>"<?php echo $room['public_age'] === $key ? ' selected' : ''; ?>><?php echo $label; ?></option><?php endforeach; ?></select><div class="form-check mb-3"><input class="form-check-input" type="checkbox" name="confirm_review" value="1" id="listing-consent" required><label class="form-check-label" for="listing-consent">Saya menyetujui tinjauan seluruh soal/kunci/sumber oleh Superadmin dan publikasi judul/ringkasan/jadwal kepada semua member setelah disetujui. Tidak ada data pribadi anak di isi. Perubahan pengajuan menyembunyikan katalog sampai ditinjau ulang.</label></div><button class="btn btn-primary">Kirim untuk ditinjau</button><?php echo form_close(); ?></details><?php endif; ?>
